INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Kommunikation > Konfliktlösung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist Konfliktlösung in der IT immer abhängig von persönlichen Gesprächen?', 2, '[{"text": "Nein", "correct": true, "because": "Digitale Kommunikation kann ebenfalls effektiv sein"}, {"text": "Ja", "correct": false, "because": "Verschiedene Methoden sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Konflikte in einem Team ohne klare Kommunikation gelöst werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation ist essenziell für Verständigung"}, {"text": "Ja", "correct": false, "because": "Ohne Kommunikation bleiben Missverständnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Teammitglieder an der Konfliktlösung beteiligt sein, um Erfolg zu haben?', 2, '[{"text": "Nein", "correct": true, "because": "Relevante Parteien reichen oft aus"}, {"text": "Ja", "correct": false, "because": "Nicht immer alle betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können ungelöste Konflikte die Effizienz eines IT-Projekts beeinträchtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Spannungen mindern Zusammenarbeit"}, {"text": "Nein", "correct": false, "because": "Konflikte haben oft negative Auswirkungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Konfliktlösung ohne Kompromissbereitschaft möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Möglich, aber oft schwieriger"}, {"text": "Nein", "correct": false, "because": "Kompromisse erleichtern Lösungen"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird häufig für die Konfliktlösung in Teams eingesetzt?', 3, '[{"text": "Mediation", "correct": true, "because": "Neutrale Vermittlung hilft"}, {"text": "Ignorieren", "correct": false, "because": "Verschärft Probleme"}, {"text": "Zufällige Entscheidung", "correct": false, "because": "Unprofessionell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist für eine erfolgreiche Konfliktlösung am wichtigsten?', 2, '[{"text": "Offene Kommunikation", "correct": true, "because": "Fördert Verständnis"}, {"text": "Technische Überlegenheit", "correct": false, "because": "Irrelevant"}, {"text": "Schnelle Entscheidungen", "correct": false, "because": "Nicht immer effektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Konfliktlösung in der Kommunikation?', 2, '[{"text": "Wiederherstellung der Zusammenarbeit", "correct": true, "because": "Fokus auf Teamharmonie"}, {"text": "Bestrafung der Konfliktparteien", "correct": false, "because": "Kontraproduktiv"}, {"text": "Verlängerung des Konflikts", "correct": false, "because": "Gegenteil ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann die Konfliktlösung verzögern?', 3, '[{"text": "Mangelnde Bereitschaft zum Zuhören", "correct": true, "because": "Blockiert Verständigung"}, {"text": "Schnelle Kompromisse", "correct": false, "because": "Kann hilfreich sein"}, {"text": "Automatische Eskalation", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten fördert die Konfliktlösung am meisten?', 2, '[{"text": "Empathie", "correct": true, "because": "Verständnis für andere Perspektiven"}, {"text": "Dominanz", "correct": false, "because": "Verschärft Konflikte"}, {"text": "Schweigen", "correct": false, "because": "Verhindert Austausch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur effektiven Konfliktlösung?', 4, '[{"text": "Problemidentifikation", "correct": true, "because": "Definiert Konflikt"}, {"text": "Offener Dialog", "correct": true, "because": "Fördert Verständnis"}, {"text": "Kompromissfindung", "correct": true, "because": "Löst Spannungen"}, {"text": "Farbauswahl der Dokumentation", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren können Konflikte in der IT verschärfen?', 3, '[{"text": "Unklare Verantwortlichkeiten", "correct": true, "because": "Führt zu Streit"}, {"text": "Mangelnde Kommunikation", "correct": true, "because": "Erhöht Missverständnisse"}, {"text": "Zeitdruck", "correct": true, "because": "Steigert Spannungen"}, {"text": "Schnelle Lösungen", "correct": false, "because": "Kein Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze unterstützen die Konfliktlösung?', 4, '[{"text": "Aktives Zuhören", "correct": true, "because": "Verständnis fördern"}, {"text": "Neutraler Moderator", "correct": true, "because": "Objektivität sichern"}, {"text": "Klarstellung der Ziele", "correct": true, "because": "Fokus auf Gemeinsames"}, {"text": "Technische Überlegenheit", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen können ungelöste Konflikte in der Teamkommunikation haben?', 3, '[{"text": "Verzögerte Projekte", "correct": true, "because": "Mangelnde Kooperation"}, {"text": "Geringere Produktivität", "correct": true, "because": "Spannungen stören"}, {"text": "Schlechte Teamstimmung", "correct": true, "because": "Motivation sinkt"}, {"text": "Schnellere Entscheidungen", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördern die Konfliktlösung?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Passt an Lösungen an"}, {"text": "Respekt", "correct": true, "because": "Schafft Vertrauen"}, {"text": "Kommunikationsfähigkeit", "correct": true, "because": "Klare Absprachen"}, {"text": "Dominanz", "correct": false, "because": "Verschärft Konflikte"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Konfliktlösung erfordert oft Kompromisse. b) Konflikte lösen sich immer von selbst.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kompromisse ja, Selbstlösung selten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Offene Kommunikation kann Konflikte entschärfen. b) Konfliktlösung ist nur bei großen Teams relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation ja, alle Teams betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mediation kann bei der Konfliktlösung helfen. b) Konflikte sind immer technischer Natur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mediation ja, Konflikte vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Unklare Ziele können Konflikte verursachen. b) Konfliktlösung erfordert keine Dokumentation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ziele ja, Dokumentation sinnvoll"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Empathie fördert die Konfliktlösung. b) Konflikte haben keine Auswirkungen auf Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Empathie ja, Auswirkungen vorhanden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

